if (!root) return;

if (item < root->val) {
    avlDelete(root->left, item);
} else if (item > root->val) {
    avlDelete(root->right, item);
} else {
    if (!root->left || !root->right) {
        TreeNode* temp = root->left ? root->left : root->right;
        if (!temp) {
            temp = root;
            root = nullptr;
        } else {
            *root = *temp;
        }
        delete temp;
    } else {
        TreeNode* succ = root->right;
        while (succ->left) succ = succ->left;
        root->val = succ->val;
        avlDelete(root->right, succ->val);
    }
}

if (!root) return;

root->height = 1 + std::max((root->left ? root->left->height : 0),
                            (root->right ? root->right->height : 0));

int balance = (root->left ? root->left->height : 0) -
              (root->right ? root->right->height : 0);

if (balance > 1) {
    int leftBalance = (root->left->left ? root->left->left->height : 0) -
                      (root->left->right ? root->left->right->height : 0);
    if (leftBalance < 0) {
        TreeNode* y = root->left;
        TreeNode* x = y->right;
        y->right = x->left;
        x->left = y;
        y->height = 1 + std::max((y->left ? y->left->height : 0),
                                 (y->right ? y->right->height : 0));
        x->height = 1 + std::max((x->left ? x->left->height : 0),
                                 (x->right ? x->right->height : 0));
        root->left = x;
    }
    TreeNode* y = root->left;
    root->left = y->right;
    y->right = root;
    root->height = 1 + std::max((root->left ? root->left->height : 0),
                                 (root->right ? root->right->height : 0));
    y->height = 1 + std::max((y->left ? y->left->height : 0),
                             (y->right ? y->right->height : 0));
    root = y;
} else if (balance < -1) {
    int rightBalance = (root->right->left ? root->right->left->height : 0) -
                       (root->right->right ? root->right->right->height : 0);
    if (rightBalance > 0) {
        TreeNode* y = root->right;
        TreeNode* x = y->left;
        y->left = x->right;
        x->right = y;
        y->height = 1 + std::max((y->left ? y->left->height : 0),
                                 (y->right ? y->right->height : 0));
        x->height = 1 + std::max((x->left ? x->left->height : 0),
                                 (x->right ? x->right->height : 0));
        root->right = x;
    }
    TreeNode* y = root->right;
    root->right = y->left;
    y->left = root;
    root->height = 1 + std::max((root->left ? root->left->height : 0),
                                 (root->right ? root->right->height : 0));
    y->height = 1 + std::max((y->left ? y->left->height : 0),
                             (y->right ? y->right->height : 0));
    root = y;
}
